import {Spinner} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {AgentIcon} from '@primer/octicons-react'
import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import type {Repository} from '@github-ui/current-repository'
import {CurrentUserProvider} from '../../contexts/CurrentUserContext'
import {TaskChat} from './TaskChat'
import {ConsecutiveCAPI401sProvider} from '../../contexts/ConsecutiveCAPI401sContext'
import {PullContextProvider} from '../../contexts/PullContext'
import {useInitializeAuthToken} from '../../hooks/use-initialize-auth-token'
import {CopilotChatProvider} from '@github-ui/copilot-chat/CopilotChatContext'
import {useChatPayload} from './hooks/use-chat-payload'
import {useTaskPayload} from './hooks/use-task-payload'
import type {ExtendedCopilotChatPayload} from './hooks/use-chat-payload'
import type {TaskPayload} from './hooks/use-task-payload'
import {ChatStreamProvider} from '../../contexts/ChatStreamContext'
import {ViewModeProvider} from '../../contexts/ViewModeContext'

export interface PullRequestAgentLogsProps {
  repository: Repository
  pullRequestNumber: number
}

const NoAgentSessions = () => (
  <Blankslate>
    <Blankslate.Visual>
      <AgentIcon size={24} />
    </Blankslate.Visual>
    <Blankslate.Heading>No agent sessions</Blankslate.Heading>
    <Blankslate.Description>No agent sessions found for this pull request.</Blankslate.Description>
  </Blankslate>
)

/**
 * Component that fetches and displays agent logs for a pull request
 */
export function PullRequestsSidePanel({repository, pullRequestNumber}: PullRequestAgentLogsProps) {
  const chatQuery = useChatPayload()
  const taskQuery = useTaskPayload(repository, pullRequestNumber)

  const isLoading = chatQuery.isLoading || taskQuery.isLoading
  const error = chatQuery.error || taskQuery.error

  if (isLoading) {
    return (
      <div className="d-flex flex-justify-center flex-items-center tmp-p-4">
        <Spinner size="medium" />
      </div>
    )
  }

  if (error) {
    if (taskQuery.error?.name === 'NotFoundError') {
      return <NoAgentSessions />
    }

    const errorMessage = error.message || 'Failed to load agent logs'
    return <div className="tmp-p-4 color-fg-danger">{errorMessage}</div>
  }

  if (!chatQuery.data || !taskQuery.data) {
    return <NoAgentSessions />
  }

  return <TaskDetailView chatPayload={chatQuery.data} taskPayload={taskQuery.data} repository={repository} />
}

interface TaskDetailViewProps {
  chatPayload: ExtendedCopilotChatPayload
  taskPayload: TaskPayload
  repository: Repository
}

function TaskDetailView({chatPayload, taskPayload, repository}: TaskDetailViewProps) {
  useInitializeAuthToken(taskPayload.initialAuthToken)

  const currentUserIsSessionOwner = !!taskPayload.sessions?.some(s => s.user_id === taskPayload.currentUser?.id)

  return (
    <ViewModeProvider mode="sidePanel">
      <CurrentRepositoryProvider repository={repository}>
        <CopilotChatProvider
          workerPath={chatPayload.findFileWorkerPath}
          threadId={null}
          refs={chatPayload.refs ?? []}
          mode="assistive"
          ssoOrganizations={chatPayload.ssoOrganizations ?? []}
          copilotChatPayload={chatPayload}
        >
          <ConsecutiveCAPI401sProvider>
            <ChatStreamProvider>
              <CurrentUserProvider
                currentUser={taskPayload.currentUser}
                currentUserIsSessionOwner={currentUserIsSessionOwner}
                optedInToFeedback={chatPayload.optedInToUserFeedback}
              >
                <PullContextProvider pull={taskPayload.pull}>
                  <TaskChat
                    {...taskPayload}
                    showHeader
                    repoOwner={repository.ownerLogin}
                    repoName={repository.name}
                    taskId={taskPayload.taskId}
                    branchAliveChannel={taskPayload.branchAliveChannel}
                    task={taskPayload.task}
                  />
                </PullContextProvider>
              </CurrentUserProvider>
            </ChatStreamProvider>
          </ConsecutiveCAPI401sProvider>
        </CopilotChatProvider>
      </CurrentRepositoryProvider>
    </ViewModeProvider>
  )
}
